update_rule.pseudocode:
if day % communication_frequency_days == 0:
  if state.risk_signal >= mandate_threshold_cases_per_100k and state.policy_mandate_flag == False:
    state.policy_mandate_flag = True
  elif state.risk_signal <= lifting_threshold_cases_per_100k and state.policy_mandate_flag == True:
    state.policy_mandate_flag = False
  # Allocate enforcement strength proportional to resources
  state.enforcement_strength = enforcement_strength_default * (1.0 if state.policy_mandate_flag else 0.5)
  # Broadcast public health message affecting perceived norms
  for person in Persons:
    trust = person.trust_in_authorities
    person.attitude_toward_masks = clip(person.attitude_toward_masks + message_strength * (2*trust - 1), -2, 2)
emit event.policy_broadcast

actions = 0
if not state.policy_mandate_flag:
  emit observable.enforcement_actions_count_daily = 0
  return
for (i,j,vid,vtype) in contacts_today:
  for pid in [i,j]:
    if not Person[pid].mask_status:
      p_detect = clip(state.enforcement_strength + normal(0, enforcement_noise), 0, 1)
      if bernoulli(p_detect):
        actions += 1
        if bernoulli(0.7):
          # On-the-spot compliance for the remainder of day
          Person[pid].mask_status = True
        else:
          apply_penalty(pid, penalty_noncompliance)
emit observable.enforcement_actions_count_daily = actions

for hh in Households:
  mean_att = mean(Person[m].attitude_toward_masks for m in hh.member_ids)
  for m in hh.member_ids:
    Person[m].attitude_toward_masks = clip(Person[m].attitude_toward_masks + household_norm_strength * (mean_att - Person[m].attitude_toward_masks), -2, 2)
    Person[m].habit_strength = clip(Person[m].habit_strength + intra_household_influence_priority * (1 if mean_att>0 else -0.2), 0, 1)
